/* Kelas VIII — Semester 1 — Tawadu, Taat & Qanaah
   10 PGK (2 jawaban benar) + 10 Benar/Salah + 10 Jawaban Singkat + 5 Essay.
   Seluruh soal HOTS dan orisinal. */



window.BSAddTypes({
'id':'k8-tawadu-ta-at-qanaah',
'pgk':[
{level:'HOTS',indicator:'Menentukan dua hubungan antara tawadu dan qanaah',text:'Saat diskusi kelompok, dua pernyataan berikut yang tepat tentang hubungan antara tawadu dan qanaah adalah ...',options:['qanaah dan tawadu tidak berkaitan karena qanaah merupakan urusan harta sedangkan tawadu merupakan urusan sikap terhadap orang lain','tawadu menghasilkan qanaah karena orang yang tidak menilai diri lebih tinggi tidak menuntut keadaan yang melebihi keperluannya','qanaah menghasilkan tawadu karena orang yang merasa cukup tidak memerlukan perbandingan dengan pihak lain untuk menilai dirinya','keduanya sama-sama mencegah sifat iri karena orang yang merasa cukup dan tidak menilai diri lebih tinggi tidak terdorong menginginkan keadaan pihak lain'],answers:[1,2],explanation:'Tawadu dan qanaah saling menguatkan melalui dua arah. Qanaah menghasilkan tawadu karena orang yang merasa cukup dengan pemberian Allah tidak memerlukan perbandingan dengan pihak lain untuk menilai dirinya, sehingga ia tidak terdorong menunjukkan kelebihan atau merendahkan orang lain. Sebaliknya tawadu menghasilkan qanaah karena orang yang tidak menilai diri lebih tinggi tidak menuntut keadaan yang melebihi keperluannya, sebab tuntutan yang berlebihan sering bersumber dari perasaan bahwa dirinya layak memperoleh lebih dari pihak lain. Keduanya juga sama-sama mencegah sifat iri karena iri timbul dari perbandingan yang tidak disertai penerimaan. Pernyataan ketiga keliru karena qanaah bukan hanya urusan harta melainkan sikap hati terhadap seluruh pemberian Allah termasuk kedudukan dan kemampuan.'},
{level:'HOTS',indicator:'Menganalisis dua hubungan qanaah dengan usaha',text:'Dalam sebuah kajian, dua pernyataan yang tepat tentang hubungan qanaah dengan usaha adalah ...',options:['orang yang qanaah tidak boleh memiliki keinginan untuk memperbaiki keadaannya karena keinginan semacam itu menunjukkan ketidakrelaan terhadap pemberian Allah','qanaah berarti tidak perlu berusaha karena hasil telah ditentukan oleh Allah sehingga usaha tidak berpengaruh terhadap keadaan seseorang','qanaah bukan berarti berhenti berusaha karena mencari rezeki yang halal tetap merupakan kewajiban bagi orang yang mampu','qanaah berkaitan dengan penerimaan terhadap hasil setelah usaha dilaksanakan sehingga tidak mengurangi semangat untuk berusaha'],answers:[2,3],explanation:'Qanaah dan usaha merupakan dua hal yang berlangsung bersamaan dan bukan saling menggantikan. Qanaah berkaitan dengan penerimaan terhadap hasil setelah usaha dilaksanakan sehingga tidak mengurangi semangat untuk berusaha, karena yang diatur oleh qanaah adalah sikap hati terhadap hasil dan bukan besarnya usaha. Qanaah juga bukan berarti berhenti berusaha, karena mencari rezeki yang halal tetap merupakan kewajiban bagi orang yang mampu dan meninggalkan usaha dengan alasan qanaah merupakan bentuk kemalasan yang mengabaikan perintah bekerja. Pernyataan ketiga keliru karena ketentuan Allah meliputi sebab dan akibatnya sehingga usaha merupakan bagian dari jalan datangnya rezeki. Pernyataan keempat juga keliru karena keinginan memperbaiki keadaan bukan tanda ketidakrelaan; yang dilarang adalah perasaan tidak pernah cukup dan iri terhadap keadaan pihak lain, sedangkan usaha untuk memperbaiki keadaan merupakan hal yang dianjurkan.'},
{level:'HOTS',indicator:'Mengevaluasi dua pernyataan tentang tawadu dalam menerima nasihat',text:'Dua pernyataan yang tepat tentang tawadu dalam menerima nasihat adalah ...',options:['menolak nasihat dengan alasan bahwa penyampainya memiliki kekurangan merupakan bentuk kesombongan karena penilaian terhadap penyampaian menggantikan penilaian terhadap isi','nasihat hanya perlu diterima dari guru atau orang tua karena pihak lain tidak memiliki kewenangan untuk menasihati','menerima nasihat dari siapa pun berarti membenarkan seluruh isi nasihat itu sehingga seseorang tidak perlu memeriksa kebenarannya terlebih dahulu','menerima nasihat dari pihak yang lebih muda atau lebih rendah kedudukannya merupakan tanda tawadu karena yang dinilai adalah isi nasihat dan bukan penyampainya'],answers:[0,3],explanation:'Tawadu dalam menerima nasihat ditunjukkan oleh dua keadaan. Pertama, menerima nasihat dari pihak yang lebih muda atau lebih rendah kedudukannya, karena yang dinilai adalah isi nasihat dan bukan kedudukan penyampainya, dan orang yang sombong biasanya menolak nasihat dengan alasan kedudukan pihak yang menyampaikannya. Kedua, menolak nasihat dengan alasan bahwa penyampainya memiliki kekurangan merupakan bentuk kesombongan karena penilaian terhadap penyampaian menggantikan penilaian terhadap isi, dan cara ini sering digunakan oleh orang yang tidak ingin memperbaiki dirinya. Pernyataan ketiga keliru karena menerima nasihat tidak berarti membenarkan seluruh isinya tanpa pemeriksaan; nasihat tetap perlu diperiksa kebenarannya dengan cara yang santun, dan pemeriksaan itu bukan bentuk kesombongan apabila dilakukan untuk memperoleh kejelasan. Pernyataan keempat juga keliru karena nasihat merupakan bagian dari hubungan antarorang beriman dan tidak dibatasi oleh kedudukan.'},
{level:'HOTS',indicator:'Mengevaluasi dua pernyataan tentang batas ketaatan',text:'Dalam kegiatan keagamaan, perhatikan pernyataan tentang batas ketaatan kepada Allah, Rasul, orang tua, dan pemimpin. Dua pernyataan yang tepat adalah ...',options:['ketaatan kepada orang tua dan pemimpin bersifat terbatas pada hal yang baik sehingga tidak berlaku ketika keduanya memerintahkan kemaksiatan','ketaatan kepada Allah dan Rasul-Nya bersifat mutlak karena keduanya tidak mungkin memerintahkan hal yang buruk','apabila orang tua memerintahkan kemaksiatan maka anak boleh menolaknya dengan cara yang keras karena perintah itu menggugurkan kewajiban menghormati keduanya','ketaatan kepada pemimpin bersifat mutlak karena pemimpin merupakan pihak yang berwenang menentukan seluruh aturan bagi masyarakat'],answers:[0,1],explanation:'Ketaatan memiliki dua tingkat yang berbeda. Ketaatan kepada Allah dan Rasul-Nya bersifat mutlak karena keduanya tidak mungkin memerintahkan hal yang buruk dan seluruh perintah-Nya mengandung kebaikan bagi manusia. Adapun ketaatan kepada orang tua dan pemimpin bersifat terbatas pada hal yang baik sehingga tidak berlaku ketika keduanya memerintahkan kemaksiatan, berdasarkan prinsip bahwa tidak ada ketaatan kepada makhluk dalam perkara bermaksiat kepada Allah. Pernyataan ketiga keliru karena kewenangan pemimpin dibatasi oleh ketentuan agama dan bukan bersifat mutlak. Pernyataan keempat juga keliru karena penolakan terhadap perintah maksiat tetap harus disampaikan dengan cara yang santun, sebab gugurnya kewajiban menaati dalam perkara itu tidak menggugurkan kewajiban berbuat baik kepada orang tua.'},
{level:'HOTS',indicator:'Menganalisis dua hubungan ketiga sifat dengan ketenangan hidup',text:'Saat diskusi kelompok, dua pernyataan yang tepat tentang hubungan tawadu, taat, dan qanaah dengan ketenangan hidup adalah ...',options:['tawadu menghasilkan ketenangan karena orang yang tidak bersaing untuk dipandang lebih tinggi tidak terbebani oleh penilaian orang lain','ketiga sifat itu tidak menghasilkan ketenangan karena orang yang bersikap demikian akan dimanfaatkan oleh pihak lain yang lebih agresif','qanaah menghasilkan ketenangan karena orang yang merasa cukup tidak terus-menerus membandingkan keadaannya dengan keadaan pihak lain','taat menghasilkan ketenangan karena orang yang melaksanakan kewajibannya tidak dibebani oleh rasa bersalah dan kekhawatiran terhadap akibat meninggalkan kewajiban'],answers:[0,2],explanation:'Ketiga sifat itu menghasilkan ketenangan hidup melalui jalan yang berbeda-beda. Tawadu menghasilkan ketenangan karena orang yang tidak bersaing untuk dipandang lebih tinggi tidak terbebani oleh penilaian orang lain, sehingga ia tidak perlu menampilkan sesuatu yang bukan keadaannya. Qanaah menghasilkan ketenangan karena orang yang merasa cukup tidak terus-menerus membandingkan keadaannya dengan keadaan pihak lain, dan perbandingan itulah yang paling sering menghasilkan kegelisahan walaupun keadaan seseorang sebenarnya baik. Taat juga menghasilkan ketenangan karena orang yang melaksanakan kewajibannya tidak dibebani oleh rasa bersalah dan kekhawatiran terhadap akibat meninggalkan kewajiban. Pernyataan keempat keliru karena ketiga sifat itu justru menjaga seseorang dari persaingan yang melelahkan, dan orang yang memanfaatkannya akan menanggung akibatnya sendiri sedangkan orang yang bersikap demikian tetap memperoleh ketenangan dan pahala.'},
{level:'HOTS',indicator:'Menganalisis dua pernyataan tepat tentang hakikat tawadu',text:'Perhatikan pernyataan tentang hakikat tawadu. Dua pernyataan yang tepat adalah ...',options:['tawadu merupakan sikap yang hanya dituntut dari orang yang keadaannya lebih rendah sehingga orang yang memiliki kedudukan tidak perlu bersikap tawadu','tawadu berarti merendahkan diri secara berlebihan sehingga seseorang tidak berani menyampaikan pendapatnya walaupun pendapatnya benar','tawadu merupakan sikap tidak menilai diri lebih tinggi dari pihak lain sehingga bersedia menerima kebenaran dari siapa pun yang menyampaikannya','tawadu tetap memungkinkan seseorang mengakui kemampuannya selama pengakuan itu tidak disertai perendahan terhadap kemampuan pihak lain'],answers:[1,2],explanation:'Tawadu adalah sikap tidak menilai diri lebih tinggi dari pihak lain sehingga bersedia menerima kebenaran dari siapa pun yang menyampaikannya, dan sikap ini tetap memungkinkan seseorang mengakui kemampuannya selama pengakuan itu tidak disertai perendahan terhadap kemampuan pihak lain. Tawadu bukan berarti mengingkari nikmat kemampuan yang telah diberikan oleh Allah, melainkan menempatkannya pada kedudukan yang benar sebagai pemberian yang bukan hasil usaha sendiri. Pernyataan kedua keliru karena merendahkan diri secara berlebihan sehingga tidak berani menyampaikan kebenaran bukan bagian dari tawadu melainkan bentuk kelemahan yang dapat merugikan pihak lain. Pernyataan keempat juga keliru karena tawadu justru paling dituntut dari orang yang memiliki kedudukan atau kelebihan, sebab kedudukan merupakan keadaan yang paling mudah mendorong seseorang kepada kesombongan.'},
{level:'HOTS',indicator:'Mengevaluasi dua keadaan yang sering disalahpahami sebagai tawadu',text:'Perhatikan keterangan berikut. Dua penilaian yang tepat atas dua keadaan berikut: seorang siswa tidak mau mengikuti lomba karena merasa tidak mampu, dan seorang siswa menerima seluruh pendapat temannya tanpa memeriksa kebenarannya adalah ...',options:['keadaan pertama merupakan tawadu yang sejati karena mengakui ketidakmampuan merupakan tanda kerendahan hati yang paling jelas','keadaan pertama bukan tawadu apabila alasannya adalah ketakutan akan kegagalan dan bukan penilaian yang jujur terhadap kemampuannya','keadaan kedua merupakan tawadu yang sejati karena tidak membantah pendapat orang lain merupakan tanda tidak sombong','keadaan kedua bukan tawadu karena menerima seluruh pendapat tanpa pemeriksaan merupakan bentuk pengabaian terhadap tanggung jawab untuk menggunakan akal'],answers:[1,3],explanation:'Kedua keadaan itu perlu dinilai dengan teliti agar tidak disalahpahami sebagai tawadu. Keadaan pertama bukan tawadu apabila alasannya adalah ketakutan akan kegagalan dan bukan penilaian yang jujur terhadap kemampuannya, karena ketakutan akan kegagalan berkaitan dengan penilaian orang lain terhadap dirinya apabila ia kalah, dan keadaan itu justru menunjukkan kepedulian terhadap pandangan manusia yang merupakan lawan dari tawadu. Keadaan kedua juga bukan tawadu karena menerima seluruh pendapat tanpa pemeriksaan merupakan bentuk pengabaian terhadap tanggung jawab untuk menggunakan akal, dan tawadu tidak berarti meninggalkan penilaian terhadap kebenaran. Tawadu yang benar adalah bersedia menerima kebenaran dari siapa pun setelah memeriksanya, dan bersedia mengakui kekurangan diri dengan jujur tanpa melebih-lebihkannya.'},
{level:'HOTS',indicator:'Menentukan dua penerapan taat bagi seorang pelajar',text:'Perhatikan pernyataan berikut. Dua penerapan berikut yang merupakan wujud ketaatan bagi seorang pelajar adalah ...',options:['melaksanakan salat pada waktunya walaupun sedang mengerjakan tugas yang tenggat waktunya dekat','mematuhi tata tertib madrasah yang tidak bertentangan dengan ketentuan agama walaupun tata tertib itu terasa memberatkan','meninggalkan salat ketika tugas sekolah menumpuk karena belajar juga merupakan bentuk ibadah yang bernilai tinggi','mematuhi permintaan teman untuk tidak melaporkan pelanggaran karena kesetiaan kepada teman merupakan bagian dari akhlak yang baik'],answers:[0,1],explanation:'Penerapan ketaatan bagi seorang pelajar diwujudkan dengan melaksanakan salat pada waktunya walaupun sedang mengerjakan tugas yang tenggat waktunya dekat, karena ibadah wajib tidak boleh ditinggalkan demi kepentingan lain dan waktu salat telah ditetapkan sehingga tidak dapat ditunda tanpa alasan yang dibenarkan. Selain itu mematuhi tata tertib madrasah yang tidak bertentangan dengan ketentuan agama juga merupakan wujud ketaatan, karena ketaatan kepada aturan yang baik merupakan bagian dari ketaatan kepada Allah selama aturan itu tidak memerintahkan kemaksiatan. Meninggalkan salat karena tugas menumpuk bukan bentuk ibadah karena meninggalkan kewajiban tidak dapat dibenarkan oleh kegiatan lain yang hukumnya lebih rendah. Mematuhi permintaan teman untuk tidak melaporkan pelanggaran juga bukan kesetiaan yang benar karena melindungi pelanggaran berarti menyetujuinya dan merugikan pihak lain.'},
{level:'HOTS',indicator:'Menganalisis dua akibat meninggalkan qanaah',text:'Perhatikan keterangan berikut. Dua akibat berikut yang timbul dari meninggalkan sikap qanaah adalah ...',options:['timbulnya sifat iri terhadap keadaan pihak lain karena ukuran kepuasan dipindahkan dari apa yang dimiliki kepada apa yang dimiliki oleh orang lain','keadaan menjadi lebih baik karena keinginan yang besar mendorong seseorang bekerja lebih keras dan memperoleh hasil yang lebih banyak','keinginan yang terus bertambah sehingga seseorang tidak pernah merasa cukup walaupun keadaannya telah berkecukupan','meninggalkan qanaah tidak berpengaruh terhadap keadaan hati karena perasaan cukup merupakan persoalan bakat dan bukan persoalan pilihan'],answers:[0,2],explanation:'Meninggalkan qanaah menghasilkan dua akibat yang saling berkaitan. Pertama, keinginan yang terus bertambah sehingga seseorang tidak pernah merasa cukup walaupun keadaannya telah berkecukupan, karena yang menjadi ukuran bukan keperluannya melainkan keinginannya yang tidak memiliki batas. Kedua, timbulnya sifat iri terhadap keadaan pihak lain karena ukuran kepuasan dipindahkan dari apa yang dimilikinya kepada apa yang dimiliki oleh orang lain, dan perpindahan ukuran ini menjadikan seseorang selalu berada dalam keadaan kurang tanpa memandang keadaan sebenarnya. Pernyataan ketiga keliru karena keinginan yang besar tidak selalu mendorong kerja keras; sering kali keinginan yang tidak terkendali justru menghasilkan jalan pintas yang melanggar ketentuan agama. Pernyataan keempat juga keliru karena perasaan cukup merupakan sikap yang dapat dilatih dan bukan bakat yang tetap, sehingga qanaah dapat dibiasakan melalui latihan.'},
{level:'HOTS',indicator:'Menentukan dua tanda orang yang telah memiliki ketiga sifat tersebut',text:'Cermati uraian berikut ini. Dua tanda berikut yang menunjukkan seseorang telah memiliki tawadu, taat, dan qanaah adalah ...',options:['tetap melaksanakan kewajiban walaupun tidak ada yang melihat dan tidak ada keuntungan yang segera diperoleh dari pelaksanaannya','merasa perlu memberitahukan setiap kebaikan yang dilakukannya agar pihak lain mengetahui bahwa ia merupakan orang yang taat','mudah berubah pendirian sesuai dengan keadaan yang paling menguntungkan bagi dirinya karena perubahan itu menunjukkan keluwesan dalam bergaul','tidak berubah perilakunya ketika memperoleh pujian atau ketika mendapat celaan karena ukuran perilakunya bukan penilaian manusia'],answers:[0,3],explanation:'Tanda orang yang telah memiliki ketiga sifat itu tampak dalam dua keadaan. Pertama, tidak berubah perilakunya ketika memperoleh pujian atau ketika mendapat celaan, karena ukuran perilakunya bukan penilaian manusia melainkan keyakinannya tentang apa yang benar; orang yang tawadu tidak menjadi sombong oleh pujian dan tidak menjadi lemah oleh celaan. Kedua, tetap melaksanakan kewajiban walaupun tidak ada yang melihat dan tidak ada keuntungan yang segera diperoleh, karena ketaatannya ditujukan kepada Allah dan bukan kepada pihak yang mengawasinya, dan qanaah menjadikannya tidak menuntut balasan yang segera. Merasa perlu memberitahukan setiap kebaikan merupakan tanda riya yang bertentangan dengan tawadu. Mudah berubah pendirian sesuai keuntungan merupakan tanda ketiadaan keteguhan yang bertentangan dengan ketaatan yang benar.'}
],
'bs':[
{level:'HOTS',indicator:'Menilai pernyataan tentang tawadu dan penerimaan kebenaran',text:'Pernyataan: Seseorang yang bersikap tawadu tetap perlu memeriksa kebenaran sebuah nasihat sebelum mengamalkannya, dan pemeriksaan itu bukan bentuk kesombongan apabila dilakukan dengan cara yang santun. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan tersebut benar. Tawadu tidak berarti menerima seluruh pendapat tanpa pemeriksaan, karena setiap orang bertanggung jawab atas amal yang dilaksanakannya dan tidak dapat menjadikan pihak lain sebagai alasan apabila amalnya keliru. Memeriksa kebenaran sebuah nasihat merupakan bagian dari menggunakan akal yang diperintahkan, dan pemeriksaan itu bukan bentuk kesombongan selama dilakukan dengan cara yang santun dan dengan tujuan memperoleh kejelasan, bukan untuk mencari kesalahan penyampainya atau untuk menunjukkan kelebihan diri sendiri.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang menolak lomba karena takut gagal',text:'Pernyataan: Tidak mau mengikuti sebuah lomba karena takut mengalami kegagalan merupakan bentuk tawadu karena menunjukkan pengakuan atas kekurangan diri. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan tersebut salah. Tidak mau mengikuti lomba karena takut mengalami kegagalan bukan bentuk tawadu, karena ketakutan akan kegagalan berkaitan dengan penilaian orang lain terhadap dirinya apabila ia kalah, dan keadaan itu justru menunjukkan kepedulian yang berlebihan terhadap pandangan manusia. Tawadu yang benar berupa penilaian yang jujur terhadap kemampuan diri, sehingga apabila seseorang memiliki kemampuan untuk mengikuti lomba maka mengikutinya merupakan bentuk penggunaan nikmat kemampuan, dan apabila hasilnya tidak baik maka ia menerimanya tanpa merasa terhina. Menghindari kesempatan untuk berusaha karena takut dinilai buruk merupakan bentuk kelemahan dan bukan kerendahan hati.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang qanaah dan usaha',text:'Pernyataan: Bersikap qanaah berarti tidak perlu berusaha memperbaiki keadaan karena hasil telah ditentukan oleh Allah sehingga usaha tidak berpengaruh. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan tersebut salah. Qanaah berkaitan dengan sikap hati terhadap hasil yang telah diperoleh setelah usaha dilaksanakan, dan bukan dengan meninggalkan usaha. Islam memerintahkan manusia untuk berusaha mencari rezeki yang halal dan memperbaiki keadaannya, sedangkan ketentuan Allah meliputi sebab dan akibatnya sehingga usaha merupakan bagian dari jalan datangnya hasil. Meninggalkan usaha dengan alasan qanaah merupakan bentuk kemalasan yang mengaburkan makna qanaah itu sendiri, karena qanaah yang benar justru menjadikan seseorang bekerja dengan tenang tanpa dibebani oleh perasaan tidak pernah cukup.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang perasaan cukup sebagai bakat',text:'Pernyataan: Perasaan cukup dengan pemberian Allah merupakan bakat yang dimiliki oleh sebagian orang sehingga orang yang tidak memilikinya tidak dapat melatihnya. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan tersebut salah. Perasaan cukup bukan bakat yang tetap melainkan sikap yang dapat dilatih melalui pembiasaan. Latihan yang dapat dilakukan antara lain membandingkan keadaan diri dengan pihak yang keadaannya lebih rendah dalam urusan dunia agar tidak meremehkan nikmat, bersyukur secara nyata atas nikmat yang masih ada, dan mengurangi kebiasaan melihat keadaan pihak lain yang lebih tinggi dalam urusan harta. Apabila perasaan cukup merupakan bakat yang tidak dapat dilatih maka perintah untuk bersikap qanaah tidak akan masuk akal, karena perintah agama selalu disertai kemampuan untuk melaksanakannya.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang ketaatan yang bergantung pada pengawasan',text:'Pernyataan: Melaksanakan kewajiban hanya ketika ada yang mengawasi merupakan tanda bahwa ketaatan seseorang belum ditujukan kepada Allah melainkan kepada penilaian manusia. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan tersebut benar secara isi karena melaksanakan kewajiban hanya ketika ada yang mengawasi memang menunjukkan bahwa pengendali perilaku seseorang adalah penilaian manusia dan bukan keyakinan kepada Allah. Ketaatan yang ditujukan kepada Allah tetap dilaksanakan dalam keadaan dilihat maupun tidak dilihat, karena yang diawasi oleh Allah tidak bergantung pada kehadiran manusia. Keadaan semacam ini juga berkaitan dengan keimanan kepada malaikat yang mencatat amal, karena kesadaran terhadap pencatatan itu menghasilkan pengendalian diri yang tidak memerlukan pengawasan manusia.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang hubungan qanaah dan sifat iri',text:'Pernyataan: Qanaah mencegah timbulnya sifat iri karena orang yang merasa cukup tidak memindahkan ukuran kepuasannya dari apa yang dimilikinya kepada apa yang dimiliki oleh pihak lain. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan tersebut benar. Sifat iri timbul dari perbandingan yang tidak disertai penerimaan, yaitu ketika seseorang menjadikan keadaan pihak lain sebagai ukuran untuk menilai keadaannya sendiri sehingga keadaannya terasa kurang walaupun sebenarnya cukup. Qanaah mencegah keadaan itu dengan menjaga agar ukuran kepuasan tetap berada pada apa yang telah diberikan oleh Allah kepadanya, sehingga keberhasilan pihak lain tidak dirasakan sebagai kekurangan bagi dirinya dan tidak menimbulkan keinginan agar nikmat itu hilang dari pihak lain.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang ketaatan kepada pemimpin',text:'Pernyataan: Ketaatan kepada pemimpin bersifat mutlak karena pemimpin memiliki kewenangan menentukan aturan bagi masyarakat yang dipimpinnya. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan tersebut salah. Ketaatan kepada pemimpin merupakan ketaatan yang terbatas pada hal yang baik, sehingga tidak berlaku ketika pemimpin memerintahkan kemaksiatan atau hal yang bertentangan dengan ketentuan agama. Prinsip yang menjadi dasarnya adalah bahwa tidak ada ketaatan kepada makhluk dalam perkara bermaksiat kepada Allah. Kewenangan pemimpin dalam menentukan aturan berlaku selama aturan itu tidak bertentangan dengan ketentuan agama, dan apabila terdapat pertentangan maka ketaatan kepada Allah didahulukan dengan tetap menjaga adab dalam menyampaikan penolakan.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang menerima nasihat dari pihak yang lebih rendah kedudukannya',text:'Pernyataan: Menerima nasihat dari pihak yang lebih muda atau lebih rendah kedudukannya merupakan tanda tawadu karena yang dinilai adalah isi nasihat dan bukan kedudukan penyampainya. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan tersebut benar. Tawadu ditunjukkan oleh kesediaan menerima kebenaran dari pihak mana pun datangnya, karena yang menjadi ukuran adalah isi nasihat dan bukan kedudukan penyampainya. Menolak nasihat dengan alasan kedudukan atau usia penyampainya merupakan bentuk kesombongan, sebab cara itu menilai kebenaran berdasarkan siapa yang menyampaikannya. Sikap tawadu semacam ini juga menghasilkan manfaat yang lebih besar karena sumber masukan menjadi lebih luas dan tidak terbatas pada pihak yang memiliki kedudukan tertentu.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang tawadu dari orang yang memiliki kedudukan',text:'Pernyataan: Tawadu justru paling dituntut dari orang yang memiliki kedudukan atau kelebihan karena kedudukan merupakan keadaan yang paling mudah mendorong seseorang kepada kesombongan. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan tersebut benar. Kedudukan, kekayaan, ilmu, dan ketampanan atau kecantikan merupakan keadaan yang paling mudah mendorong seseorang kepada kesombongan karena keadaan itu menghasilkan penghormatan dari orang lain dan perasaan lebih tinggi. Oleh karena itu orang yang memilikinya lebih memerlukan tawadu daripada orang yang tidak memilikinya, dan tawadu dalam keadaan memiliki kelebihan merupakan bentuk kerendahan hati yang lebih besar nilainya karena memerlukan pengendalian diri yang lebih kuat.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang tawadu dan pengakuan kemampuan',text:'Pernyataan: Tawadu tidak berarti mengingkari kemampuan yang dimiliki seseorang, karena mengingkari nikmat kemampuan juga merupakan bentuk ketidakbersyukuran. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan tersebut benar. Tawadu merupakan sikap tidak menilai diri lebih tinggi dari pihak lain dan tidak merendahkan pihak lain, sehingga mengakui kemampuan yang dimiliki secara jujur bukan bentuk kesombongan selama tidak disertai perasaan lebih mulia. Sebaliknya mengingkari kemampuan yang telah diberikan oleh Allah merupakan bentuk ketidakbersyukuran atas nikmat itu, dan dapat menyebabkan seseorang meninggalkan tanggung jawab yang sebenarnya mampu dilaksanakannya. Tawadu yang benar menempatkan kemampuan sebagai amanah yang perlu digunakan untuk kebaikan dan bukan sebagai bahan untuk merasa lebih tinggi.'}
],
'singkat':[
{level:'HOTS',indicator:'Menyebutkan lawan dari qanaah',text:'Sikap tidak pernah merasa cukup dan terus menuntut tambahan walaupun keadaannya telah berkecukupan disebut ...',answer:'tamak',accepted:['rakus','serakah','halap','keinginan berlebihan'],explanation:'Tamak atau serakah adalah sikap tidak pernah merasa cukup dan terus menuntut tambahan walaupun keadaannya telah berkecukupan, dan merupakan lawan dari qanaah. Tamak menghasilkan keinginan yang terus bertambah sehingga seseorang tidak pernah merasa puas dengan apa yang dimilikinya, dan sering mendorong orang untuk memperoleh tambahan dengan cara yang tidak dibenarkan. Tamak juga menghasilkan kegelisahan karena ukuran kepuasan dipindahkan dari apa yang dimiliki kepada apa yang belum dimiliki.'},
{level:'HOTS',indicator:'Menyebutkan istilah perasaan tidak senang atas nikmat yang diperoleh pihak lain',text:'Perasaan tidak senang atas nikmat yang diperoleh pihak lain dan menginginkan agar nikmat itu hilang darinya disebut ...',answer:'hasad',accepted:['iri hati','dengki','hasud','iri'],explanation:'Hasad atau iri hati adalah perasaan tidak senang atas nikmat yang diperoleh pihak lain disertai keinginan agar nikmat itu hilang darinya. Hasad merupakan lawan dari qanaah karena orang yang hasad menjadikan keadaan pihak lain sebagai ukuran untuk menilai keadaannya sendiri, sehingga nikmat yang telah dimilikinya terasa kurang walaupun jumlahnya tidak berubah. Hasad juga merusak amal kebaikan sebagaimana disebutkan dalam sebuah keterangan agama, dan berbeda dari ghibthah yaitu keinginan memperoleh nikmat yang sama tanpa mengharapkan hilangnya nikmat itu dari pihak lain, yang dibolehkan dalam urusan kebaikan.'},
{level:'HOTS',indicator:'Menyebutkan istilah tidak menjadikan dunia sebagai tujuan utama',text:'Sikap tidak menjadikan dunia sebagai tujuan utama sehingga tidak terikat olehnya namun tetap menunaikan kewajibannya disebut ...',answer:'zuhud',accepted:['zuhud terhadap dunia','tidak cinta dunia','qanaah terhadap dunia'],explanation:'Zuhud adalah sikap tidak menjadikan dunia sebagai tujuan utama sehingga tidak terikat olehnya, namun tetap menunaikan kewajiban mencari rezeki dan menggunakan dunia untuk keperluan akhirat. Zuhud bukan berarti meninggalkan dunia atau menolak rezeki yang halal, melainkan menempatkan dunia pada kedudukannya sebagai sarana dan bukan sebagai tujuan. Zuhud berkaitan erat dengan qanaah karena keduanya merupakan keadaan hati yang tidak dikuasai oleh keinginan terhadap apa yang belum dimiliki, dan berkaitan dengan tawadu karena orang yang tidak terikat oleh dunia tidak memerlukan pengakuan manusia untuk merasa bernilai.'},
{level:'HOTS',indicator:'Menyebutkan wujud tawadu seorang murid ketika memperoleh nasihat dari gurunya',text:'Wujud tawadu yang ditunjukkan oleh seorang murid ketika memperoleh nasihat dari gurunya, yaitu memperbaiki kesalahannya tanpa membantah dan tanpa merasa direndahkan di hadapan teman-temannya, disebut sikap ....',answer:'menerima nasihat',accepted:['menerima nasihat','menerima teguran','menerima koreksi','lapang dada menerima nasihat'],explanation:'Sikap itu adalah menerima nasihat. Kedudukannya menunjukkan bahwa tawadu kepada guru diuji pada saat guru menyampaikan koreksi, karena pada saat itulah perasaan ingin membela diri paling kuat muncul. Pembedaannya dari menerima nasihat yang bertentangan dengan ketentuan agama penting karena ketaatan kepada makhluk hanya berlaku dalam perkara kebaikan, sehingga nasihat yang mengarah kepada perbuatan yang dilarang tidak wajib diterima dan perlu disampaikan dengan cara yang tetap menjaga penghormatan kepada guru.'},
{level:'HOTS',indicator:'Menyebutkan wujud tawadu ketika menerima pendapat pihak lain dalam pembahasan bersama',text:'Wujud tawadu yang ditunjukkan dengan bersedia menerima pendapat pihak lain walaupun pendapat itu disampaikan oleh orang yang lebih muda atau lebih rendah kedudukannya, selama pendapat itu disertai alasan yang lebih kuat, disebut sikap ....',answer:'menghargai pendapat',accepted:['menghargai pendapat','menerima pendapat orang lain','menghormati pendapat','menghargai pendapat orang lain'],explanation:'Sikap itu adalah menghargai pendapat. Kedudukannya menunjukkan bahwa tawadu diuji dalam keadaan ketika pendapat sendiri tidak diterima, karena pihak yang merasa lebih tinggi cenderung menolak pendapat yang datang dari pihak yang dianggap lebih rendah. Pembedaannya dari menerima seluruh pendapat penting karena pendapat yang bertentangan dengan ketentuan agama tidak boleh diterima walaupun disampaikan dengan alasan yang meyakinkan, sehingga penghargaan terhadap pendapat tetap berada dalam batas kebenaran dan bukan dalam batas kesopanan semata.'},
{level:'HOTS',indicator:'Menyebutkan keadaan hati orang yang qanaah terhadap pembagian rezeki',text:'Keadaan hati yang menerima pembagian rezeki yang telah diterimanya dan tidak membandingkannya dengan pembagian yang diterima pihak lain, sehingga tidak timbul keinginan yang melampaui keperluannya, disebut sikap ....',answer:'merasa cukup',accepted:['merasa cukup','cukup','keadaan merasa cukup','rela dengan pembagian'],explanation:'Keadaan itu adalah merasa cukup. Kedudukannya merupakan inti qanaah sehingga qanaah tidak berarti berhenti berusaha melainkan tidak menggantungkan ketenangan hati pada tambahan yang belum diperoleh. Pembedaannya dari keadaan malas penting karena pihak yang merasa cukup tetap melaksanakan usaha sesuai kemampuannya dan tetap menunaikan kewajiban terhadap pihak yang menjadi tanggungannya, sedangkan pihak yang berhenti berusaha dengan alasan merasa cukup telah menempatkan qanaah pada kedudukan yang tidak semestinya.'},
{level:'HOTS',indicator:'Menyebutkan istilah keteguhan dalam ketaatan',text:'Sikap tetap melaksanakan ketaatan secara terus-menerus walaupun menghadapi rintangan disebut ...',answer:'istiqamah',accepted:['istiqomah','konsisten','teguh','keteguhan'],explanation:'Istiqamah adalah sikap tetap melaksanakan ketaatan secara terus-menerus walaupun menghadapi rintangan atau hasilnya belum tampak. Istiqamah berkaitan erat dengan ketaatan karena ketaatan yang benar bukan ketaatan yang bersifat sementara ketika keadaan menguntungkan, melainkan ketaatan yang bertahan dalam berbagai keadaan. Istiqamah juga berkaitan dengan tawadu karena orang yang istiqamah tidak memerlukan pujian untuk melanjutkan kebaikannya dan tidak berhenti karena celaan.'},
{level:'HOTS',indicator:'Menyebutkan istilah melaksanakan perintah dan menjauhi larangan',text:'Sikap melaksanakan perintah dan menjauhi larangan pihak yang berwenang dalam hal yang baik disebut ...',answer:'taat',accepted:['ketaatan','patuh','kepatuhan'],explanation:'Taat adalah sikap melaksanakan perintah dan menjauhi larangan pihak yang berwenang dalam hal yang baik. Ketaatan kepada Allah dan Rasul-Nya bersifat mutlak karena keduanya tidak mungkin memerintahkan hal yang buruk, sedangkan ketaatan kepada orang tua, guru, dan pemimpin bersifat terbatas pada hal yang baik sehingga tidak berlaku ketika keduanya memerintahkan kemaksiatan. Prinsip yang menjadi dasarnya adalah bahwa tidak ada ketaatan kepada makhluk dalam perkara bermaksiat kepada Allah.'},
{level:'HOTS',indicator:'Menyebutkan sifat tidak bersaing untuk dipandang lebih tinggi',text:'Sikap tidak berupaya menampilkan diri agar dipandang lebih tinggi dari pihak lain merupakan bagian dari ...',answer:'tawadu',accepted:['kerendahan hati','rendah hati','tidak pamer'],explanation:'Sikap tidak berupaya menampilkan diri agar dipandang lebih tinggi dari pihak lain merupakan bagian dari tawadu, karena tawadu bukan hanya berkaitan dengan penilaian terhadap diri sendiri melainkan juga dengan perilaku menampilkan diri. Orang yang tawadu tidak memerlukan pengakuan dari orang lain untuk merasa bernilai, sehingga ia tidak menambah amal atau penampilan karena kehadiran penonton dan tidak menguranginya karena ketiadaan penonton.'},
{level:'HOTS',indicator:'Menyebutkan prinsip tidak ada ketaatan kepada makhluk dalam maksiat',text:'Prinsip yang menyatakan bahwa tidak ada ketaatan kepada makhluk dalam perkara bermaksiat kepada ... merupakan batas seluruh ketaatan kepada selain Allah.',answer:'Allah',accepted:['Allah swt','tuhan','khalik'],explanation:'Prinsip tidak ada ketaatan kepada makhluk dalam perkara bermaksiat kepada Allah merupakan batas seluruh ketaatan kepada selain Allah, termasuk ketaatan kepada orang tua, guru, pemimpin, dan suami atau istri. Prinsip ini menjadikan ketaatan kepada makhluk bersifat terbatas pada hal yang baik, sehingga ketika perintah itu bertentangan dengan ketentuan agama maka kewajiban menaatinya gugur namun kewajiban berbuat baik dan menyampaikan penolakan dengan cara yang santun tetap berlaku.'}
],
'essay':[
{level:'HOTS',indicator:'Mengevaluasi dua pemahaman yang keliru tentang qanaah',text:'Dua orang menyampaikan pendapat tentang qanaah. Pendapat pertama: qanaah berarti tidak boleh memiliki keinginan untuk memperoleh keadaan yang lebih baik karena keinginan semacam itu menunjukkan ketidakrelaan terhadap pemberian Allah. Pendapat kedua: qanaah berarti menerima apa adanya tanpa perlu berusaha karena Allah telah menentukan bagian setiap orang. Evaluasilah kedua pendapat tersebut dan jelaskan pemahaman yang benar tentang qanaah beserta dua alasannya!',key:'Evaluasi pendapat pertama: pendapat ini keliru karena menyamakan keinginan memperbaiki keadaan dengan ketidakrelaan terhadap pemberian Allah, padahal keduanya merupakan hal yang berbeda. Keinginan memperbaiki keadaan merupakan dorongan alami yang bahkan diperlukan untuk melaksanakan tanggung jawab, misalnya keinginan memperoleh ilmu yang lebih banyak agar dapat bekerja dengan lebih baik atau keinginan memperoleh penghasilan yang cukup agar dapat menafkahi keluarga dan menunaikan zakat. Yang tergolong ketidakrelaan adalah perasaan tidak pernah cukup disertai keluhan terhadap ketentuan Allah dan iri terhadap keadaan pihak lain, dan perasaan semacam itu dapat ada walaupun keadaan seseorang tidak berubah. Dengan demikian yang dinilai adalah arah keinginan itu dan bukan ada atau tidaknya keinginan. Evaluasi pendapat kedua: pendapat ini juga keliru karena menjadikan qanaah sebagai alasan untuk meninggalkan usaha, padahal qanaah berkaitan dengan sikap hati terhadap hasil dan bukan dengan besar kecilnya usaha. Menyerahkan bagian setiap orang kepada ketentuan Allah merupakan keyakinan yang benar, namun ketentuan Allah meliputi sebab dan akibatnya sehingga usaha merupakan bagian dari jalan datangnya bagian itu; meninggalkan usaha dengan alasan bahwa bagian telah ditentukan merupakan kesalahpahaman yang sama dengan meninggalkan amal karena takut tidak ikhlas, yaitu menggunakan keyakinan yang benar untuk membenarkan perbuatan yang tidak diperintahkan. Pemahaman yang benar tentang qanaah: qanaah adalah merasa cukup dan ridha dengan pemberian Allah setelah melaksanakan usaha sesuai kemampuan, sehingga qanaah memiliki dua unsur yaitu usaha yang sungguh-sungguh dan penerimaan terhadap hasilnya. Alasan pertama: dengan rumusan ini qanaah tidak bertentangan dengan perintah berusaha karena unsur usaha termasuk di dalamnya, dan qanaah justru menjadikan usaha lebih tenang sebab orang yang berusaha tidak dibebani oleh kegelisahan tentang hasil; ia bekerja dengan sungguh-sungguh dan menyerahkan hasilnya kepada Allah, sehingga kegagalan tidak menghancurkannya dan keberhasilan tidak menjadikannya sombong. Alasan kedua: dengan rumusan ini qanaah dapat dibedakan dari kemalasan dan dari tamak secara jelas. Qanaah berbeda dari kemalasan karena kemalasan tidak melaksanakan usaha sedangkan qanaah melaksanakannya, dan berbeda dari tamak karena tamak tidak menerima hasil walaupun telah berusaha sedangkan qanaah menerimanya. Pembedaan ini penting agar qanaah tidak digunakan sebagai nama lain bagi kemalasan dan agar usaha memperbaiki keadaan tidak dicurigai sebagai tanda ketiadaan qanaah.',rubric:['Mengevaluasi pendapat pertama dengan membedakan keinginan memperbaiki keadaan dari ketidakrelaan terhadap pemberian Allah.','Mengevaluasi pendapat kedua dengan menjelaskan bahwa qanaah berkaitan dengan sikap hati terhadap hasil dan bukan dengan besar kecilnya usaha.','Merumuskan pemahaman yang benar tentang qanaah dengan menyebut dua unsurnya yaitu usaha yang sungguh-sungguh dan penerimaan terhadap hasilnya.','Menyertakan dua alasan yang menunjukkan bahwa rumusan itu tidak bertentangan dengan perintah berusaha dan dapat membedakan qanaah dari kemalasan serta dari tamak.'],explanation:'Soal ini menuntut kemampuan menilai dua pemahaman keliru yang sama-sama menggunakan istilah agama sebagai dasarnya, lalu merumuskan pemahaman yang benar disertai alasan yang mampu membedakan konsep itu dari dua konsep yang berseberangan. Jawaban yang baik menunjukkan bahwa kedua pendapat keliru itu berasal dari kesamaan kesalahan, yaitu mengambil satu bagian dari ajaran lalu menjadikannya alasan untuk meninggalkan bagian yang lain.'},
{level:'HOTS',indicator:'Menganalisis keterkaitan tiga sifat dalam satu kasus nyata',text:'Seorang siswa dipilih menjadi ketua kelas padahal terdapat teman lain yang lebih pandai. Setelah terpilih ia mulai menampilkan diri agar dipuji, merasa tidak perlu mendengar pendapat teman yang lebih pandai itu, dan meminta agar seluruh keputusan kelas mengikuti keinginannya. Analisislah keadaan tersebut dengan menunjukkan sifat tercela yang muncul, sifat yang hilang, dan tiga langkah perbaikan yang dapat ditempuhnya!',key:'Analisis sifat tercela yang muncul: dalam keadaan itu muncul tiga sifat tercela sekaligus. Pertama, takabur karena ia merasa tidak perlu mendengar pendapat teman yang lebih pandai, yang menunjukkan bahwa ia menilai dirinya lebih tinggi berdasarkan kedudukannya sebagai ketua dan bukan berdasarkan kemampuannya. Kedua, riya karena ia mulai menampilkan diri agar dipuji, sehingga tujuan perilakunya bergeser dari melaksanakan tanggung jawab kepada memperoleh pengakuan dari teman-temannya. Ketiga, keinginan menguasai karena ia meminta agar seluruh keputusan kelas mengikuti keinginannya, yang merupakan bentuk penggunaan amanah untuk kepentingan diri sendiri dan bukan untuk kepentingan bersama. Analisis sifat yang hilang: tiga sifat terpuji telah hilang dari keadaannya. Tawadu hilang karena ia tidak lagi bersedia menerima kebenaran dari pihak yang kedudukannya lebih rendah atau yang tidak menyukainya. Qanaah hilang karena ia tidak merasa cukup dengan kedudukan yang telah diberikan kepadanya dan menuntut pengakuan serta kekuasaan yang lebih besar dari kewenangannya. Taat hilang karena ia menggunakan kedudukan untuk memaksakan keinginannya dan bukan untuk melaksanakan tanggung jawab sesuai aturan yang berlaku di kelas itu, dan ketaatan kepada amanah menuntut agar keputusan diambil dengan memperhatikan kepentingan seluruh anggota kelas. Tiga langkah perbaikan. Langkah pertama: mengembalikan cara pengambilan keputusan kepada musyawarah dengan secara aktif meminta pendapat seluruh anggota kelas termasuk teman yang lebih pandai itu, lalu mencatat pendapat yang disampaikan dan menjelaskan alasan apabila pendapat itu tidak dapat diterima; langkah ini perlu didahulukan karena perbaikan yang paling mudah diperiksa adalah perubahan cara bekerja dan bukan sekadar perubahan perasaan, dan dengan meminta pendapat secara aktif ia melatih tawadu secara nyata. Langkah kedua: menahan diri dari menampilkan diri dengan tidak menyampaikan kedudukannya kepada pihak di luar kelas dan tidak mengaitkan keberhasilan kelas dengan dirinya sendiri, melainkan menyebut keberhasilan itu sebagai hasil kerja bersama; langkah ini melatih keikhlasan karena dorongan untuk dipuji paling kuat ketika seseorang memegang kedudukan yang tampak, dan menahannya merupakan latihan yang nyata. Langkah ketiga: menetapkan batas kewenangannya secara tertulis bersama wali kelas, yaitu daftar hal yang menjadi keputusannya sendiri dan daftar hal yang harus dimusyawarahkan, sehingga permintaannya agar seluruh keputusan mengikuti keinginannya tidak terulang karena batas itu telah jelas dan dapat diperiksa oleh anggota kelas; langkah ini perlu karena kesalahpahaman tentang batas kewenangan sering menjadi jalan bagi penyalahgunaan amanah, dan kejelasan batas melindungi baik ketua maupun anggota kelas.',rubric:['Menyebutkan tiga sifat tercela yang muncul dalam kasus tersebut beserta penjelasan yang merujuk pada perilaku spesifik dalam kasus.','Menyebutkan tiga sifat terpuji yang hilang beserta penjelasan mengapa masing-masing hilang dalam keadaan itu.','Menyusun langkah pertama berupa pengembalian cara pengambilan keputusan kepada musyawarah beserta alasan mendahulukannya.','Menyusun langkah kedua dan ketiga berupa menahan diri dari menampilkan diri dan penetapan batas kewenangan secara tertulis, masing-masing disertai alasan.'],explanation:'Soal ini menuntut kemampuan mengurai sebuah kasus yang mengandung beberapa sifat tercela sekaligus lalu menghubungkannya dengan sifat terpuji yang hilang, dan menghasilkan perbaikan yang bersifat struktural dan bukan hanya berupa nasihat. Jawaban yang baik menunjukkan bahwa perbaikan memerlukan perubahan cara bekerja yang dapat diperiksa, karena perubahan perasaan saja tidak cukup ketika kedudukan yang mendorong sifat itu masih dipegang.'},
{level:'HOTS',indicator:'Menganalisis sebab sifat tawadu sulit dipertahankan ketika memperoleh kelebihan',text:'Banyak orang yang bersikap rendah hati ketika keadaannya biasa namun berubah menjadi sombong setelah memperoleh kelebihan berupa kedudukan, kekayaan, atau ketenaran. Analisislah tiga sebab terjadinya perubahan tersebut dan jelaskan tiga cara untuk menjaga tawadu ketika kelebihan itu telah diperoleh!',key:'Tiga sebab terjadinya perubahan. Sebab pertama: kelebihan menghasilkan perlakuan yang berbeda dari orang lain, karena orang yang memiliki kedudukan atau kekayaan biasanya memperoleh penghormatan, didahulukan dalam berbicara, dan jarang dibantah; perlakuan yang berlangsung terus-menerus ini menghasilkan perasaan bahwa dirinya memang layak memperoleh kedudukan yang lebih tinggi, sehingga penilaian orang lain terhadapnya perlahan-lahan menjadi penilaiannya terhadap dirinya sendiri. Sebab kedua: kelebihan menjauhkan seseorang dari pihak yang dapat mengingatkannya, karena orang yang telah memiliki kedudukan jarang berada dalam keadaan yang memungkinkan orang lain menegurnya; bawahan atau orang yang memerlukannya cenderung tidak menyampaikan kekurangan yang dilihatnya sehingga umpan balik yang diperlukan untuk mengenali diri sendiri menjadi tidak ada, dan tanpa umpan balik seseorang tidak menyadari perubahan yang terjadi pada dirinya. Sebab ketiga: kelebihan sering diperoleh setelah usaha yang panjang sehingga orang itu menghubungkannya dengan kemampuannya sendiri dan melupakan bahwa kemampuan dan kesempatan itu merupakan pemberian Allah; hubungan yang keliru ini menghasilkan perasaan berhak atas kelebihan itu dan perasaan berhak merupakan akar dari kesombongan, karena orang yang merasa berhak akan menuntut pengakuan dan merendahkan pihak yang tidak memberikannya. Tiga cara menjaga tawadu. Cara pertama: mengingat asal keadaan dirinya dengan secara sengaja tetap berhubungan dengan kalangan yang mengenalnya sebelum memperoleh kelebihan, misalnya keluarga, tetangga lama, atau teman sekolah dahulu, karena kalangan itu tidak menilai dirinya berdasarkan kedudukannya yang sekarang dan dapat menyampaikan kekurangan yang tidak disampaikan oleh orang lain; hubungan ini berfungsi sebagai umpan balik yang menggantikan umpan balik yang hilang akibat kedudukannya. Cara kedua: menempatkan kelebihan sebagai amanah yang akan dimintai pertanggungjawabannya dengan secara teratur memeriksa penggunaan kelebihan itu, yaitu apakah kedudukannya digunakan untuk melayani pihak yang dipimpinnya atau untuk memperoleh kemudahan bagi dirinya, apakah kekayaannya digunakan untuk menunaikan zakat dan membantu pihak yang memerlukan atau hanya untuk menambah kemewahan, dan apakah ketenarannya digunakan untuk menyampaikan hal yang bermanfaat atau untuk memperoleh perhatian; pemeriksaan yang teratur mengubah kelebihan dari sesuatu yang dimiliki menjadi sesuatu yang dititipkan, dan kesadaran sebagai penerima titipan merupakan dasar dari tawadu. Cara ketiga: melatih diri menerima koreksi dan melayani orang lain secara nyata, misalnya dengan melaksanakan sendiri pekerjaan yang dapat dilakukan tanpa bantuan walaupun telah memiliki kedudukan, dan dengan meminta koreksi secara aktif kepada pihak yang dipercaya lalu menerimanya tanpa membela diri; latihan ini perlu karena kesombongan tumbuh melalui kebiasaan dilayani dan dibenarkan, sehingga lawannya hanya dapat dibentuk melalui kebiasaan melayani dan kebiasaan menerima koreksi.',rubric:['Menjelaskan sebab pertama berupa perlakuan berbeda dari orang lain yang menghasilkan perasaan layak memperoleh kedudukan lebih tinggi.','Menjelaskan sebab kedua berupa hilangnya umpan balik karena orang lain tidak lagi menyampaikan kekurangan kepadanya.','Menjelaskan sebab ketiga berupa penghubungan kelebihan dengan kemampuan sendiri dan perasaan berhak atas kelebihan itu.','Menjelaskan tiga cara menjaga tawadu yang masing-masing menjawab sebab yang telah disebut, bukan cara yang bersifat umum.'],explanation:'Soal ini menuntut analisis tentang mengapa sebuah sifat sulit dipertahankan dalam keadaan tertentu, sehingga jawaban yang baik harus menjelaskan mekanisme perubahan dan bukan hanya menyebut bahwa keadaan itu berbahaya. Poin penting yang perlu muncul adalah bahwa kesombongan tumbuh melalui perlakuan orang lain dan hilangnya umpan balik, sehingga cara menjaganya harus mengembalikan kedua hal itu melalui hubungan dengan kalangan yang mengenal keadaan semula dan melalui latihan menerima koreksi.'},
{level:'HOTS',indicator:'Merancang program pembiasaan tiga sifat selama satu bulan',text:'Susunlah sebuah program pembiasaan tawadu, taat, dan qanaah selama satu bulan untuk siswa kelas VIII di sebuah madrasah. Program itu harus memuat satu kegiatan untuk setiap sifat, pihak yang terlibat, dan cara mengetahui bahwa sifat itu benar-benar terlatih!',key:'Program pembiasaan satu bulan dengan satu kegiatan untuk setiap sifat. Kegiatan pertama untuk tawadu, dilaksanakan pada pekan pertama dan kedua, yaitu latihan menerima koreksi dan melayani. Setiap siswa meminta satu koreksi tentang dirinya kepada tiga pihak yang berbeda yaitu seorang guru, seorang teman sebaya, dan seorang anggota keluarga, dengan pertanyaan yang sama yaitu satu hal yang perlu diperbaikinya, dan tidak boleh membela diri ketika menerimanya; selain itu setiap siswa melaksanakan satu bentuk layanan tanpa diminta setiap pekan, misalnya merapikan tempat ibadah sebelum orang lain datang, membersihkan papan tulis, atau membantu petugas kebersihan madrasah. Pihak yang terlibat adalah siswa, guru, teman sebaya, anggota keluarga, dan wali kelas sebagai pendamping. Cara mengetahui sifat itu terlatih: jumlah siswa yang berhasil menyelesaikan permintaan koreksi kepada tiga pihak tanpa membela diri, dan perbedaan kemudahan yang dirasakan siswa ketika menerima koreksi dari guru dan dari teman sebaya yang dituliskan dalam refleksi pribadinya; siswa yang melaporkan bahwa menerima koreksi dari teman sebaya terasa lebih sulit namun berhasil melakukannya menunjukkan latihan tawadu yang nyata, karena menerima koreksi dari pihak yang setara merupakan ujian tawadu yang paling sulit. Kegiatan kedua untuk taat, dilaksanakan pada pekan ketiga, yaitu catatan pelaksanaan kewajiban tanpa pengawasan. Setiap siswa membuat daftar tiga kewajiban hariannya yaitu satu kewajiban ibadah, satu kewajiban di madrasah, dan satu kewajiban di rumah, lalu menandai pelaksanaannya setiap hari tanpa diperiksa oleh siapa pun; pada akhir pekan siswa menghitung jumlah hari yang terlaksana dan menuliskan satu keterangan tentang kewajibannya yang paling sering terlewat beserta sebabnya. Pihak yang terlibat adalah siswa, orang tua yang diminta memberikan keterangan singkat pada akhir pekan tentang kewajiban di rumah, dan wali kelas sebagai pemeriksa kelengkapan catatan. Cara mengetahui sifat itu terlatih: jumlah hari yang terlaksana dari dua puluh satu hari yang direncanakan untuk ketiga kewajiban itu, dan kejujuran siswa dalam menandai pelaksanaannya yang dapat diperiksa dengan membandingkan catatan siswa dan keterangan orang tua untuk kewajiban di rumah; apabila terdapat perbedaan antara keduanya maka hal itu menjadi bahan pembahasan tentang arti taat ketika tidak ada yang memeriksa, karena ketaatan yang terlatih adalah ketaatan yang tetap dilaksanakan tanpa pengawasan dan dicatat dengan jujur. Kegiatan ketiga untuk qanaah, dilaksanakan pada pekan keempat, yaitu latihan menunda satu keinginan dan latihan bersyukur secara tertulis. Setiap siswa memilih satu keinginan yang biasa dipenuhinya, misalnya membeli jajanan tertentu, membeli barang yang sedang tren, atau menggunakan waktu untuk hiburan, lalu menundanya selama satu pekan penuh; bersamaan dengan itu setiap siswa menuliskan tiga hal yang telah dimilikinya setiap malam disertai satu kalimat tentang cara hal itu bermanfaat baginya. Pihak yang terlibat adalah siswa, orang tua sebagai pihak yang mengetahui keinginan yang ditunda, dan guru agama sebagai pembimbing dalam penulisan syukur. Cara mengetahui sifat itu terlatih: jumlah siswa yang berhasil menunda keinginannya selama satu pekan penuh dan isi tulisan syukur yang menunjukkan keragaman, yaitu apakah siswa menuliskan hal yang sama setiap hari atau mampu melihat nikmat yang berbeda-beda termasuk nikmat yang biasanya tidak disadarinya; kemampuan melihat nikmat yang tidak biasa disadari merupakan tanda bahwa perasaan cukup sedang terbentuk, karena orang yang tidak qanaah cenderung hanya melihat apa yang belum dimilikinya dan tidak melihat apa yang telah dimilikinya. Penutup program: pada akhir bulan diadakan satu pertemuan untuk membahas tiga pertanyaan secara umum tanpa menyebut nama, yaitu hal yang paling sulit dalam menerima koreksi, hal yang paling sering menyebabkan kewajiban terlewat, dan keinginan yang paling sulit ditunda; kemudian setiap siswa menetapkan satu kebiasaan dari ketiga kegiatan itu untuk dilanjutkan secara pribadi, karena tujuan pembiasaan adalah terbentuknya sifat yang menetap dan bukan pelaksanaan kegiatan selama satu bulan.',rubric:['Merancang kegiatan pertama untuk tawadu beserta pihak yang terlibat dan cara mengetahui keberhasilan yang merujuk pada kesulitan menerima koreksi dari teman sebaya.','Merancang kegiatan kedua untuk taat beserta cara mengetahui keberhasilan yang mencakup kejujuran dalam pencatatan dan perbandingan dengan keterangan orang tua.','Merancang kegiatan ketiga untuk qanaah beserta cara mengetahui keberhasilan yang merujuk pada keragaman isi tulisan syukur dan kemampuan melihat nikmat yang tidak biasa disadari.','Menyajikan rencana penutup berupa pembahasan kesulitan secara umum dan penetapan kebiasaan pribadi yang berlanjut setelah program berakhir.'],explanation:'Soal ini menuntut kemampuan merancang pembiasaan untuk tiga sifat batin yang tidak dapat diukur melalui ujian tertulis, sehingga jawaban yang baik harus menghasilkan kegiatan yang menempatkan siswa pada keadaan yang menguji sifat itu secara nyata dan ukuran keberhasilan yang berkaitan dengan kesulitan yang dirasakan, bukan hanya dengan jumlah kegiatan yang dilaksanakan.'},
{level:'HOTS',indicator:'Menyusun penerapan tiga sifat dalam tiga lingkup kehidupan',text:'Jelaskan satu penerapan nyata tawadu, taat, dan qanaah dalam tiga lingkup kehidupan berikut: di lingkungan keluarga, di lingkungan madrasah, dan di lingkungan masyarakat, sehingga seluruhnya berjumlah sembilan penerapan!',key:'Lingkup keluarga. Penerapan tawadu: bersedia menerima teguran dari adik atau kakak tentang kesalahannya sendiri dan tidak menjadikan usia sebagai alasan untuk menolak, serta tidak malu membantu pekerjaan rumah walaupun pekerjaan itu dianggap rendah seperti mencuci piring atau membersihkan lantai. Penerapan taat: melaksanakan perintah orang tua dalam hal yang baik seperti menjaga adik, memberitahukan keperluannya ketika hendak keluar rumah, dan menunaikan kewajiban membantu sesuai kesepakatan keluarga tanpa perlu diingatkan berulang kali. Penerapan qanaah: tidak menuntut kepada orang tua untuk dibelikan barang yang dimiliki oleh teman-temannya apabila keadaan keluarga tidak memungkinkan, dan tetap berterima kasih atas apa yang telah diberikan sehingga orang tua tidak merasa terbebani oleh tuntutan yang terus bertambah. Lingkup madrasah. Penerapan tawadu: bertanya kepada guru atau teman ketika belum memahami pelajaran tanpa merasa malu atau khawatir dianggap bodoh, dan menerima nilai yang lebih rendah dari teman tanpa merendahkan teman itu atau mencari kesalahan dalam penilaiannya. Penerapan taat: mematuhi tata tertib madrasah yang tidak bertentangan dengan ketentuan agama seperti datang tepat waktu, mengenakan seragam sesuai ketentuan, dan melaksanakan tugas piket walaupun tidak ada yang mengawasi pelaksanaannya. Penerapan qanaah: menerima hasil ulangan yang telah diperoleh dengan memeriksa bagian yang perlu diperbaiki dan bukan dengan membandingkan hasilnya dengan hasil teman, serta tidak merasa kurang apabila sarana belajar yang dimilikinya lebih sederhana daripada sarana milik temannya. Lingkup masyarakat. Penerapan tawadu: bersedia mengikuti kegiatan kerja bakti atau rapat warga tanpa menuntut kedudukan tertentu, dan menerima keputusan bersama yang tidak sesuai dengan usulannya selama keputusan itu tidak bertentangan dengan ketentuan agama. Penerapan taat: mematuhi aturan yang berlaku di lingkungan tempat tinggalnya seperti aturan jam malam, aturan penggunaan fasilitas bersama, dan kewajiban melaporkan keperluan administrasi, serta tidak melanggar aturan itu walaupun tidak ada yang mengetahuinya. Penerapan qanaah: tidak merasa rendah diri ketika menghadiri acara warga dengan pakaian atau kendaraan yang sederhana, dan tidak menjadikan keadaan tetangga yang lebih mampu sebagai ukuran untuk menilai keberhasilan keluarganya sendiri, sehingga hubungan bertetangga tetap baik tanpa persaingan dalam penampilan. Kesembilan penerapan itu menunjukkan bahwa ketiga sifat tersebut dapat diamalkan dalam keadaan yang berbeda-beda dan tidak memerlukan kedudukan atau kemampuan khusus, karena yang menjadi dasarnya adalah sikap hati yang dapat dipilih oleh siapa pun dalam keadaan apa pun.',rubric:['Menyajikan tiga penerapan untuk lingkup keluarga yang masing-masing sesuai dengan sifatnya dan spesifik dalam bentuk perilakunya.','Menyajikan tiga penerapan untuk lingkup madrasah yang masing-masing sesuai dengan sifatnya dan spesifik dalam bentuk perilakunya.','Menyajikan tiga penerapan untuk lingkup masyarakat yang masing-masing sesuai dengan sifatnya dan spesifik dalam bentuk perilakunya.','Menunjukkan bahwa kesembilan penerapan tidak tumpang tindih dan disertai simpulan tentang kemungkinan mengamalkannya dalam keadaan apa pun.'],explanation:'Soal ini menuntut kemampuan menerapkan tiga konsep pada tiga lingkup yang berbeda sehingga menghasilkan sembilan penerapan yang tidak tumpang tindih. Jawaban yang baik menyajikan penerapan yang spesifik dalam bentuk perilaku yang dapat diamati dan bukan pernyataan umum, serta menunjukkan bahwa setiap sifat memiliki bentuk penerapan yang berbeda dalam setiap lingkup.'}
]
});
